// components/Navbar.js
import React from 'react';
import { useAuth } from '../context/AuthContext';

const Navbar = () => {
  const { user, cart } = useAuth();

  // ✅ Функция для перехода в профиль на нужную вкладку
  const goToProfileTab = (tab) => {
    console.log('Going to profile tab:', tab);
    if (tab === 'profile') {
      window.location.hash = '#profile';
    } else {
      window.location.hash = `#profile?tab=${tab}`;
    }
  };

  // Виджет корзины
  const CartWidget = () => (
    <div 
      className="relative cursor-pointer"
      onClick={() => goToProfileTab('cart')}
    >
      <span>🛒</span>
      {cart.length > 0 && (
        <span className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full w-5 h-5 text-xs flex items-center justify-center">
          {cart.length}
        </span>
      )}
    </div>
  );

  // Виджет избранного
  const FavoritesWidget = () => (
    <div 
      className="cursor-pointer"
      onClick={() => goToProfileTab('favorites')}
    >
      ❤️
    </div>
  );

  return (
    <nav className="flex justify-between items-center p-4 bg-white shadow-md">
      {/* Логотип и другие элементы */}
      <div 
        className="cursor-pointer"
        onClick={() => { window.location.hash = '#catalog'; }}
      >
        Логотип
      </div>

      {user && (
        <div className="flex items-center space-x-4">
          <FavoritesWidget />
          <CartWidget />
          <div 
            className="cursor-pointer"
            onClick={() => goToProfileTab('profile')}
          >
            👤 Профиль
          </div>
        </div>
      )}
    </nav>
  );
};

export default Navbar;
